  4  import {Script, console2} from "forge-std/Script.sol";
  5  import {TimelockController} from "@openzeppelin/contracts/governance/TimelockController.sol";
  6  import {IVotes} from "@openzeppelin/contracts/governance/utils/IVotes.sol";
  7  import {DAOGovernanceToken} from "../contracts/DAOGovernanceToken.sol";
  8  import {EnterpriseDAO} from "../contracts/EnterpriseDAO.sol";
  9  import {DAOTreasuryExecutionEngine} from "../contracts/DAOTreasuryExecutionEngine.sol";
 10  
 11  /// @title Deploy
 12  /// @notice Bootstrap deployment for the Enterprise DAO ecosystem following the sequence
 13  ///         documented in `contracts/DAODeploymentNotes.sol`.
 14  ///
 15  ///         Trust topology after this script:
 16  ///         Token holders -> Governor -> TimelockController -> TreasuryExecutionEngine
 17  ///
 18  ///         Required environment variables:
 19  ///         - INITIAL_RECIPIENT   address receiving the full initial token supply (multisig)
 20  ///         - GUARDIAN_ADDRESS   emergency guardian (recommend an audited multisig)
 21  ///
 22  ///         Optional environment variables (defaults shown):
 23  ///         - TOKEN_NAME            "Enterprise DAO Token"
 24  ///         - TOKEN_SYMBOL          "EDAO"
 25  ///         - INITIAL_SUPPLY        100_000_000e18
 26  ///         - TIMELOCK_MIN_DELAY    2 days
 27  ///         - GOV_VOTING_DELAY      7200    (blocks, ~1 day at 12s blocks)
 28  ///         - GOV_VOTING_PERIOD     30240   (blocks, ~3.5 days)
 29  ///         - GOV_QUORUM_MIN_BPS    400     (4%)
 30  ///         - GOV_QUORUM_MAX_BPS    1000    (10%)
 31  ///         - GOV_THRESHOLD         250_000e18 (0.25% of default supply)
 32  ///
 33  ///         FINAL MANUAL STEP (not automated on purpose): after verifying all roles, the
 34  ///         deployer must renounce its temporary DEFAULT_ADMIN_ROLE on the timelock, e.g.
 35  ///         `cast send <timelock> "renounceRole(bytes32,address)" <DEFAULT_ADMIN_ROLE>
 36  ///         <deployer>`. Renouncing is deliberately left manual so a misconfiguration can
 37  ///         still be corrected before governance becomes self-sovereign.
 38  contract Deploy is Script {
 39      struct DeployParams {
 40          string tokenName;
 41          string tokenSymbol;
 42          address initialRecipient;
 43          uint256 initialSupply;
 44          address guardian;
 45          uint256 timelockMinDelay;
 46          uint48 votingDelay;
 47          uint32 votingPeriod;
 48          uint256 proposalThreshold;
 49          uint256 quorumMinBps;
 50          uint256 quorumMaxBps;
 51      }
 52  
 53      function run() external {
 54          DeployParams memory params = _readParams();
 55  
 56          vm.startBroadcast();
 57  
 58          // ------------------------------------------------------------------
 59          // 1. Governance token (fixed supply, minted once)
 60          // ------------------------------------------------------------------
 61          DAOGovernanceToken token =
 62              new DAOGovernanceToken(params.tokenName, params.tokenSymbol, params.initialRecipient, params.initialSupply);
 63          console2.log("DAOGovernanceToken:", address(token));
 64  
 65          // ------------------------------------------------------------------
 66          // 2. Timelock: open execution, deployer as temporary admin
 67          // ------------------------------------------------------------------
 68          TimelockController timelock = _deployTimelock(params.timelockMinDelay);
 69  
 70          // ------------------------------------------------------------------
 71          // 3. Treasury: timelock becomes GOVERNANCE_ROLE, guardian gets GUARDIAN_ROLE
 72          // ------------------------------------------------------------------
 73          DAOTreasuryExecutionEngine treasury = new DAOTreasuryExecutionEngine(address(timelock), params.guardian);
 74          console2.log("DAOTreasuryExecutionEngine:", address(treasury));
 75  
 76          // ------------------------------------------------------------------
 77          // 4. Governor
 78          // ------------------------------------------------------------------
 79          EnterpriseDAO governor = _deployGovernor(token, timelock, params);
 80          console2.log("EnterpriseDAO:", address(governor));
 81  
 82          // ------------------------------------------------------------------
 83          // 5. Wire the governor into the timelock
 84          // ------------------------------------------------------------------
 85          timelock.grantRole(timelock.PROPOSER_ROLE(), address(governor));
 86          timelock.grantRole(timelock.CANCELLER_ROLE(), address(governor));
 87          // EXECUTOR_ROLE is already open via address(0).
 88  
 89          vm.stopBroadcast();
 90  
 91          // ------------------------------------------------------------------
 92          // Post-deployment assertions: the deployment FAILS LOUDLY if any
 93          // wiring assumption is broken, rather than shipping a misconfigured DAO.
 94          // ------------------------------------------------------------------
 95          _assertWiring(token, timelock, treasury, governor, params);
 96      }
 97  
 98      function _assertWiring(
 99          DAOGovernanceToken token,
100          TimelockController timelock,
101          DAOTreasuryExecutionEngine treasury,
102          EnterpriseDAO governor,
103          DeployParams memory params
104      ) internal view {
105          // --- Timelock <-> Governor wiring -------------------------------------
106          bytes32 proposerRole = timelock.PROPOSER_ROLE();
107          bytes32 cancellerRole = timelock.CANCELLER_ROLE();
108          bytes32 executorRole = timelock.EXECUTOR_ROLE();
109          require(timelock.hasRole(proposerRole, address(governor)), "governor missing PROPOSER_ROLE");
110          require(timelock.hasRole(cancellerRole, address(governor)), "governor missing CANCELLER_ROLE");
111          require(timelock.hasRole(executorRole, address(0)), "executor role not open");
112          require(timelock.getMinDelay() == params.timelockMinDelay, "timelock delay mismatch");
113  
114          // --- Treasury <-> Timelock/Guardian ----------------------------------
115          require(treasury.hasRole(treasury.GOVERNANCE_ROLE(), address(timelock)), "timelock not treasury governance");
116          require(treasury.hasRole(treasury.GUARDIAN_ROLE(), params.guardian), "guardian not set on treasury");
117          require(
118              !treasury.hasRole(treasury.GOVERNANCE_ROLE(), address(governor)),
119              "governor must reach treasury only via the timelock"
120          );
121  
122          // --- Governor parameters ---------------------------------------------
123          require(governor.votingDelay() == params.votingDelay, "voting delay mismatch");
124          require(governor.votingPeriod() == params.votingPeriod, "voting period mismatch");
125          require(governor.proposalThreshold() == params.proposalThreshold, "proposal threshold mismatch");
126          require(governor.timelock() == address(timelock), "governor wired to wrong timelock");
127          require(address(governor.token()) == address(token), "governor wired to wrong token");
128  
129          // --- Quorum ramp --------------------------------------------------------
130          require(governor.dynamicQuorumMinBps() == params.quorumMinBps, "quorum min mismatch");
131          require(governor.dynamicQuorumMaxBps() == params.quorumMaxBps, "quorum max mismatch");
132          require(
133              governor.quorumLowSupplyThreshold() == params.initialSupply / 4,
134              "quorum low threshold mismatch (expected initialSupply/4)"
135          );
136          require(
137              governor.quorumHighSupplyThreshold() == (params.initialSupply * 9) / 10,
138              "quorum high threshold mismatch (expected initialSupply*9/10)"
139          );
140  
141          // --- Token ---------------------------------------------------------------
142          require(token.totalSupply() == params.initialSupply, "token supply mismatch");
143          require(token.balanceOf(params.initialRecipient) == params.initialSupply, "bootstrap supply not delivered");
144  
145          // --- Treasury tiers ---------------------------------------------------
146          (uint48 lowDelay, uint256 lowCap, bool lowEnabled) = treasury.tierConfig(treasury.TIER_LOW());
147          require(lowEnabled, "TIER_LOW disabled");
148          require(lowDelay == 1 days, "TIER_LOW delay mismatch");
149          require(lowCap == 250 ether, "TIER_LOW cap mismatch");
150  
151          // ------------------------------------------------------------------
152          // Post-deployment report
153          // ------------------------------------------------------------------
154          console2.log("--------------------------------------------------------");
155          console2.log("All post-deployment wiring assertions passed.");
156          console2.log("Bootstrap complete. Verify, then renounce the deployer");
157          console2.log("admin role on the timelock:");
158          console2.log("  cast send", address(timelock));
159          console2.log("    \"renounceRole(bytes32,address)\"");
160          console2.log("    <DEFAULT_ADMIN_ROLE> <deployer>");
161          console2.log("--------------------------------------------------------");
162          console2.log("Trust topology:");
163          console2.log("  token holders -> governor -> timelock -> treasury");
164      }
165  
166      function _readParams() internal view returns (DeployParams memory params) {
167          params.tokenName = vm.envOr("TOKEN_NAME", string("Enterprise DAO Token"));
168          params.tokenSymbol = vm.envOr("TOKEN_SYMBOL", string("EDAO"));
169          params.initialRecipient = vm.envAddress("INITIAL_RECIPIENT");
170          params.initialSupply = vm.envOr("INITIAL_SUPPLY", uint256(100_000_000e18));
171          params.guardian = vm.envAddress("GUARDIAN_ADDRESS");
172          params.timelockMinDelay = vm.envOr("TIMELOCK_MIN_DELAY", uint256(2 days));
173          params.votingDelay = uint48(vm.envOr("GOV_VOTING_DELAY", uint256(7_200)));
174          params.votingPeriod = uint32(vm.envOr("GOV_VOTING_PERIOD", uint256(30_240)));
175          params.proposalThreshold = vm.envOr("GOV_THRESHOLD", uint256(250_000e18));
176          params.quorumMinBps = vm.envOr("GOV_QUORUM_MIN_BPS", uint256(400));
177          params.quorumMaxBps = vm.envOr("GOV_QUORUM_MAX_BPS", uint256(1000));
178      }
179  
180      function _deployTimelock(uint256 minDelay) internal returns (TimelockController timelock) {
181          address[] memory noProposers = new address[](0);
182          address[] memory openExecutors = new address[](1);
183          openExecutors[0] = address(0); // EXECUTOR_ROLE open to anyone
184          timelock = new TimelockController(minDelay, noProposers, openExecutors, msg.sender);
185          console2.log("TimelockController:", address(timelock));
186      }
187  
188      function _deployGovernor(DAOGovernanceToken token, TimelockController timelock, DeployParams memory params)
189          internal
190          returns (EnterpriseDAO governor)
191      {
192          // Supply thresholds for the linear quorum ramp: 25% .. 90% of initial supply.
193          // Threshold bounds: 0.1x .. 4x the initial threshold.
194          EnterpriseDAO.GovernorConfig memory config = EnterpriseDAO.GovernorConfig({
195              name: "Enterprise DAO",
196              token: IVotes(address(token)),
197              timelock: timelock,
