261      /// @notice Execute a governance-approved package after its quarantine delay.
262      /// @dev Permissionless execution prevents a dead executor from permanently locking
263      ///      ready funds. Payable (with an explicit rejection of attached value) so that
264      ///      accidental ETH is refunded with a named error instead of a bare revert.
265      function executePackage(bytes32 packageId)
266          external
267          payable
268          whenNotPaused
269          nonReentrant
270          returns (bytes memory returnData)
271      {
272          if (msg.value != 0) revert UnexpectedMsgValue(msg.value);
273          return _executePackage(packageId);
274      }
