 98      function _assertWiring(
 99          DAOGovernanceToken token,
100          TimelockController timelock,
101          DAOTreasuryExecutionEngine treasury,
102          EnterpriseDAO governor,
103          DeployParams memory params
104      ) internal view {
105          // --- Timelock <-> Governor wiring -------------------------------------
106          bytes32 proposerRole = timelock.PROPOSER_ROLE();
107          bytes32 cancellerRole = timelock.CANCELLER_ROLE();
108          bytes32 executorRole = timelock.EXECUTOR_ROLE();
109          require(timelock.hasRole(proposerRole, address(governor)), "governor missing PROPOSER_ROLE");
110          require(timelock.hasRole(cancellerRole, address(governor)), "governor missing CANCELLER_ROLE");
111          require(timelock.hasRole(executorRole, address(0)), "executor role not open");
112          require(timelock.getMinDelay() == params.timelockMinDelay, "timelock delay mismatch");
113  
114          // --- Treasury <-> Timelock/Guardian ----------------------------------
115          require(treasury.hasRole(treasury.GOVERNANCE_ROLE(), address(timelock)), "timelock not treasury governance");
116          require(treasury.hasRole(treasury.GUARDIAN_ROLE(), params.guardian), "guardian not set on treasury");
117          require(
118              !treasury.hasRole(treasury.GOVERNANCE_ROLE(), address(governor)),
119              "governor must reach treasury only via the timelock"
120          );
121  
122          // --- Governor parameters ---------------------------------------------
123          require(governor.votingDelay() == params.votingDelay, "voting delay mismatch");
124          require(governor.votingPeriod() == params.votingPeriod, "voting period mismatch");
125          require(governor.proposalThreshold() == params.proposalThreshold, "proposal threshold mismatch");
126          require(governor.timelock() == address(timelock), "governor wired to wrong timelock");
127          require(address(governor.token()) == address(token), "governor wired to wrong token");
128  
129          // --- Quorum ramp --------------------------------------------------------
130          require(governor.dynamicQuorumMinBps() == params.quorumMinBps, "quorum min mismatch");
131          require(governor.dynamicQuorumMaxBps() == params.quorumMaxBps, "quorum max mismatch");
132          require(
133              governor.quorumLowSupplyThreshold() == params.initialSupply / 4,
134              "quorum low threshold mismatch (expected initialSupply/4)"
135          );
136          require(
137              governor.quorumHighSupplyThreshold() == (params.initialSupply * 9) / 10,
138              "quorum high threshold mismatch (expected initialSupply*9/10)"
139          );
140  
141          // --- Token ---------------------------------------------------------------
142          require(token.totalSupply() == params.initialSupply, "token supply mismatch");
143          require(token.balanceOf(params.initialRecipient) == params.initialSupply, "bootstrap supply not delivered");
144  
145          // --- Treasury tiers ---------------------------------------------------
146          (uint48 lowDelay, uint256 lowCap, bool lowEnabled) = treasury.tierConfig(treasury.TIER_LOW());
147          require(lowEnabled, "TIER_LOW disabled");
148          require(lowDelay == 1 days, "TIER_LOW delay mismatch");
149          require(lowCap == 250 ether, "TIER_LOW cap mismatch");
150  
151          // ------------------------------------------------------------------
152          // Post-deployment report
153          // ------------------------------------------------------------------
154          console2.log("--------------------------------------------------------");
155          console2.log("All post-deployment wiring assertions passed.");
156          console2.log("Bootstrap complete. Verify, then renounce the deployer");
157          console2.log("admin role on the timelock:");
158          console2.log("  cast send", address(timelock));
159          console2.log("    \"renounceRole(bytes32,address)\"");
160          console2.log("    <DEFAULT_ADMIN_ROLE> <deployer>");
161          console2.log("--------------------------------------------------------");
162          console2.log("Trust topology:");
163          console2.log("  token holders -> governor -> timelock -> treasury");
164      }
