201      ///      0 means "no expiry". `predecessor` is another package that must execute first.
202      function approvePackage(
203          address target,
204          uint256 value,
205          bytes calldata data,
206          uint8 tier,
207          uint48 expiresAt,
208          bytes32 predecessor
209      ) external onlyRole(GOVERNANCE_ROLE) returns (bytes32 packageId) {
210          if (target == address(0)) revert InvalidTarget();
211          if (tier > MAX_TIER) revert InvalidTier(tier);
212          if (targetAllowlistEnabled && !targetAllowlist[target]) revert TargetNotAllowed(target);
213  
214          TierConfig memory config = tierConfig[tier];
215          if (!config.enabled) revert TierDisabled(tier);
216          if (value > config.maxNativeValue) revert NativeValueTooHigh(value, config.maxNativeValue);
217  
218          uint48 executeAfter = uint48(block.timestamp + config.delay);
219          if (expiresAt != 0 && expiresAt <= executeAfter) revert ExpiryWindowTooShort(executeAfter, expiresAt);
220  
221          // A predecessor must exist and not already be finalized as cancelled; cycles are
222          // impossible because nonce strictly increases, but self-reference is still rejected.
223          if (predecessor != bytes32(0)) {
224              Package storage pred = _packages[predecessor];
225              if (pred.target == address(0)) revert PackageNotFound(predecessor);
226              if (predecessor == bytes32(0)) revert PredecessorCycle(packageId, predecessor); // unreachable, guard
227          }
228  
229          uint256 nonce = nextPackageNonce++;
230          packageId = keccak256(abi.encode(address(this), target, value, keccak256(data), tier, nonce));
231          _packages[packageId] = Package({
232              target: target,
233              value: value,
234              data: data,
235              executeAfter: executeAfter,
236              tier: tier,
237              executed: false,
238              cancelled: false,
239              nonce: nonce,
240              expiresAt: expiresAt,
241              predecessor: predecessor
242          });
243  
244          bytes32 dataHash = keccak256(data);
245          emit PackageApprovedV2(packageId, target, value, tier, nonce, executeAfter, expiresAt, predecessor, dataHash);
246      }
