 14  /// @title DAOTreasuryExecutionEngine
 15  /// @notice Multi-asset treasury with governance-approved, delayed execution packages.
 16  /// @dev The TimelockController should hold governance authority over this contract.
 17  ///      Every package binds target/value/calldata/tier/nonce into an immutable package id.
 18  ///      Execution is permissionless after the package's tier delay, improving liveness.
 19  ///
 20  ///      Guardian power is deliberately time-bound: a guardian may cancel a package only
 21  ///      while it is still in quarantine (before its `executeAfter` timepoint). Once the
 22  ///      quarantine window has elapsed, cancellation is a governance-only decision, so a
 23  ///      compromised guardian cannot permanently suppress execution of approved packages.
 24  contract DAOTreasuryExecutionEngine is AccessControl, Pausable, ReentrancyGuard, ERC721Holder, ERC1155Holder {
 25      using SafeERC20 for IERC20;
 26  
