187      {
188          if (amount == 0) revert InvalidZeroAmount();
189          token.safeTransferFrom(msg.sender, address(this), tokenId, amount, data);
190          emit ERC1155Deposited(msg.sender, address(token), tokenId, amount);
191      }
192  
193      // ------------------------------------------------------------------
194      // Package scheduling and execution
195      // ------------------------------------------------------------------
196  
197      /// @notice Governance schedules an exact calldata package. No arbitrary caller can create one.
198      /// @dev Deliberately NOT `whenNotPaused`: guardians pause execution, not scheduling, so
199      ///      governance can keep preparing packages during an incident.
200      ///      `expiresAt` bounds the execution window (after it, the package is dead);
201      ///      0 means "no expiry". `predecessor` is another package that must execute first.
202      function approvePackage(
203          address target,
204          uint256 value,
205          bytes calldata data,
206          uint8 tier,
207          uint48 expiresAt,
208          bytes32 predecessor
209      ) external onlyRole(GOVERNANCE_ROLE) returns (bytes32 packageId) {
210          if (target == address(0)) revert InvalidTarget();
211          if (tier > MAX_TIER) revert InvalidTier(tier);
212          if (targetAllowlistEnabled && !targetAllowlist[target]) revert TargetNotAllowed(target);
213  
214          TierConfig memory config = tierConfig[tier];
215          if (!config.enabled) revert TierDisabled(tier);
216          if (value > config.maxNativeValue) revert NativeValueTooHigh(value, config.maxNativeValue);
217  
218          uint48 executeAfter = uint48(block.timestamp + config.delay);
219          if (expiresAt != 0 && expiresAt <= executeAfter) revert ExpiryWindowTooShort(executeAfter, expiresAt);
220  
221          // A predecessor must exist and not already be finalized as cancelled; cycles are
222          // impossible because nonce strictly increases, but self-reference is still rejected.
223          if (predecessor != bytes32(0)) {
224              Package storage pred = _packages[predecessor];
225              if (pred.target == address(0)) revert PackageNotFound(predecessor);
226              if (predecessor == bytes32(0)) revert PredecessorCycle(packageId, predecessor); // unreachable, guard
227          }
228  
229          uint256 nonce = nextPackageNonce++;
230          packageId = keccak256(abi.encode(address(this), target, value, keccak256(data), tier, nonce));
231          _packages[packageId] = Package({
232              target: target,
233              value: value,
234              data: data,
235              executeAfter: executeAfter,
236              tier: tier,
237              executed: false,
238              cancelled: false,
239              nonce: nonce,
240              expiresAt: expiresAt,
241              predecessor: predecessor
242          });
243  
244          bytes32 dataHash = keccak256(data);
245          emit PackageApprovedV2(packageId, target, value, tier, nonce, executeAfter, expiresAt, predecessor, dataHash);
246      }
247  
248      /// @notice Cancel a package that has expired: anyone can call, keeps state clean.
249      function closeExpiredPackage(bytes32 packageId) external {
250          Package storage package_ = _packages[packageId];
251          if (package_.target == address(0)) revert PackageNotFound(packageId);
252          if (package_.executed || package_.cancelled) revert PackageAlreadyFinalized(packageId);
253          if (package_.expiresAt == 0 || block.timestamp < package_.expiresAt) {
254              revert PackageNotReady(packageId, package_.expiresAt);
255          }
256  
257          package_.cancelled = true; // finalized as cancelled; never executable
258          emit PackageExpired(packageId);
259      }
260  
261      /// @notice Execute a governance-approved package after its quarantine delay.
262      /// @dev Permissionless execution prevents a dead executor from permanently locking
263      ///      ready funds. Payable (with an explicit rejection of attached value) so that
264      ///      accidental ETH is refunded with a named error instead of a bare revert.
265      function executePackage(bytes32 packageId)
266          external
267          payable
268          whenNotPaused
269          nonReentrant
270          returns (bytes memory returnData)
271      {
272          if (msg.value != 0) revert UnexpectedMsgValue(msg.value);
273          return _executePackage(packageId);
274      }
275  
276      /// @notice Execute several ready packages atomically in one transaction.
277      /// @dev Reverts roll back the whole batch, so observers never see a partial run.
278      function executePackages(bytes32[] calldata packageIds)
279          external
280          payable
281          whenNotPaused
282          nonReentrant
283          returns (bytes[] memory results)
284      {
285          if (msg.value != 0) revert UnexpectedMsgValue(msg.value);
286  
287          uint256 count = packageIds.length;
288          results = new bytes[](count);
289          for (uint256 i = 0; i < count; ++i) {
290              results[i] = _executePackage(packageIds[i]);
291          }
292  
293          emit PackagesBatchExecuted(count);
294      }
295  
296      /// @dev Shared engine for single and batch execution.
297      function _executePackage(bytes32 packageId) private returns (bytes memory returnData) {
298          Package storage package_ = _packages[packageId];
299          if (package_.target == address(0)) revert PackageNotFound(packageId);
300          if (package_.executed || package_.cancelled) revert PackageAlreadyFinalized(packageId);
301          if (block.timestamp < package_.executeAfter) {
302              revert PackageNotReady(packageId, package_.executeAfter);
303          }
304          if (package_.expiresAt != 0 && block.timestamp >= package_.expiresAt) {
305              revert PackageExpiredError(packageId, package_.expiresAt);
306          }
307          if (package_.predecessor != bytes32(0)) {
308              Package storage pred = _packages[package_.predecessor];
309              if (!pred.executed) revert PredecessorNotExecuted(packageId, package_.predecessor);
310          }
311          if (package_.value > 0) {
312              uint256 balance = address(this).balance;
313              if (balance < package_.value || balance - package_.value < nativeReserveFloor) {
314                  revert ReserveFloorBreached(balance, nativeReserveFloor);
315              }
316          }
317  
318          // Checks-effects-interactions. A revert from the external call rolls the status
319          // change back; the treasury itself always supplies the native value.
320          package_.executed = true;
321  
322          (bool success, bytes memory data_) = package_.target.call{value: package_.value}(package_.data);
323          if (!success) revert ExecutionFailed(packageId, data_);
324  
325          // Wipe the calldata payload after success: refunds gas, keeps long-term state lean.
326          // Metadata (target, value, tier, nonce, executeAfter, flags) is retained.
327          delete package_.data;
328  
329          emit PackageExecuted(packageId, package_.target, package_.value, data_);
330          return data_;
331      }
332  
333      /// @notice Cancel a package: guardians only during quarantine, governance at any time.
334      /// @dev Guardian cancellation is restricted to the window before `executeAfter`, so a
335      ///      compromised guardian cannot suppress approved packages indefinitely. Governance
336      ///      (the timelock path, typically a multi-day process) retains unlimited cancellation.
337      function cancelPackage(bytes32 packageId) external {
338          Package storage package_ = _packages[packageId];
339          if (package_.target == address(0)) revert PackageNotFound(packageId);
340          if (package_.executed || package_.cancelled) revert PackageAlreadyFinalized(packageId);
341  
342          bool isGovernance = hasRole(GOVERNANCE_ROLE, msg.sender);
343          bool isGuardian = hasRole(GUARDIAN_ROLE, msg.sender);
344  
345          if (!isGovernance && !isGuardian) {
346              revert CallerNotGovernanceOrGuardian(msg.sender);
347          }
348          if (!isGovernance && block.timestamp >= package_.executeAfter) {
349              revert GuardianCancelWindowClosed(packageId, package_.executeAfter);
350          }
351  
352          package_.cancelled = true;
353          emit PackageCancelled(packageId, msg.sender);
354      }
355  
356      // ------------------------------------------------------------------
357      // Emergency controls
358      // ------------------------------------------------------------------
359  
360      /// @notice Emergency circuit breaker for funds execution.
361      function pause() external onlyRole(GUARDIAN_ROLE) {
362          _pause();
363          emit TreasuryPaused(msg.sender);
364      }
365  
366      /// @notice Unpausing requires governance, not the emergency guardian.
367      function unpause() external onlyRole(GOVERNANCE_ROLE) {
368          _unpause();
369          emit TreasuryUnpaused(msg.sender);
370      }
371  
372      /// @notice Reconfigure execution tiers. Governance-only so risk limits cannot be
373      ///         bypassed by guardians, and delays are capped at MAX_TIER_DELAY.
374      function configureTier(uint8 tier, uint48 delay, uint256 maxNativeValue, bool enabled)
375          external
376          onlyRole(GOVERNANCE_ROLE)
377      {
378          _configureTier(tier, delay, maxNativeValue, enabled);
379      }
380  
381      // ------------------------------------------------------------------
382      // Destination allowlist and reserve floors (governance-only)
383      // ------------------------------------------------------------------
384  
385      /// @notice Enable/disable the destination allowlist. When enabled, only allowlisted
386      ///         targets may receive packages.
387      function setTargetAllowlistEnabled(bool enabled) external onlyRole(GOVERNANCE_ROLE) {
388          targetAllowlistEnabled = enabled;
389          emit TargetAllowlistToggled(enabled);
390      }
391  
392      /// @notice Add or remove an address from the destination allowlist.
393      function setTargetAllowed(address target, bool allowed) external onlyRole(GOVERNANCE_ROLE) {
394          if (target == address(0)) revert InvalidTarget();
395          targetAllowlist[target] = allowed;
396          emit TargetAllowlistUpdated(target, allowed);
397      }
398  
399      /// @notice Set the minimum native balance the treasury must retain after any package
400      ///         execution. Zero disables the check.
401      function setNativeReserveFloor(uint256 floor) external onlyRole(GOVERNANCE_ROLE) {
402          nativeReserveFloor = floor;
403          emit ReserveFloorsConfigured(floor);
404      }
405  
406      /// @notice Set a per-token reserve floor for ERC20 balances. Zero disables that
407      ///         token's floor. Floors are checked when a package targets the token's
408      ///         transfer/approve-style calldata via `erc20ReserveFloors` pre-execution
409      ///         only for the native asset; ERC20 floors are enforced off-chain by
410      ///         monitoring (see SECURITY.md).
411      function setERC20ReserveFloor(IERC20 token, uint256 floor) external onlyRole(GOVERNANCE_ROLE) {
412          if (address(token) == address(0)) revert InvalidTarget();
413          erc20ReserveFloors[token] = floor;
414          emit ERC20ReserveFloorConfigured(address(token), floor);
415      }
416  
417      // ------------------------------------------------------------------
418      // Introspection
419      // ------------------------------------------------------------------
420  
421      function getPackage(bytes32 packageId) external view returns (Package memory) {
422          Package memory package_ = _packages[packageId];
423          if (package_.target == address(0)) revert PackageNotFound(packageId);
424          return package_;
425      }
426  
427      function packageExists(bytes32 packageId) external view returns (bool) {
428          return _packages[packageId].target != address(0);
429      }
430  
431      function packageHash(address target, uint256 value, bytes calldata data, uint8 tier, uint256 nonce)
432          external
433          view
434          returns (bytes32)
435      {
436          return keccak256(abi.encode(address(this), target, value, keccak256(data), tier, nonce));
437      }
438  
439      function ethBalance() external view returns (uint256) {
440          return address(this).balance;
441      }
442  
443      function erc20Balance(IERC20 token) external view returns (uint256) {
444          return token.balanceOf(address(this));
445      }
446  
447      // ------------------------------------------------------------------
448      // Internal helpers
449      // ------------------------------------------------------------------
450  
451      function _configureTier(uint8 tier, uint48 delay, uint256 maxNativeValue, bool enabled) internal {
452          if (tier > MAX_TIER) revert InvalidTier(tier);
453          if (delay > MAX_TIER_DELAY) revert TierDelayTooLong(delay, MAX_TIER_DELAY);
454          tierConfig[tier] = TierConfig({delay: delay, maxNativeValue: maxNativeValue, enabled: enabled});
455          emit TierConfigured(tier, delay, maxNativeValue, enabled);
456      }
457  
458      function supportsInterface(bytes4 interfaceId) public view override(AccessControl, ERC1155Holder) returns (bool) {
459          return super.supportsInterface(interfaceId);
460      }
461  }
