  2  pragma solidity ^0.8.24;
  3  
  4  import {Governor} from "@openzeppelin/contracts/governance/Governor.sol";
  5  import {GovernorSettings} from "@openzeppelin/contracts/governance/extensions/GovernorSettings.sol";
  6  import {GovernorCountingSimple} from "@openzeppelin/contracts/governance/extensions/GovernorCountingSimple.sol";
  7  import {GovernorVotes} from "@openzeppelin/contracts/governance/extensions/GovernorVotes.sol";
  8  import {GovernorTimelockControl} from "@openzeppelin/contracts/governance/extensions/GovernorTimelockControl.sol";
  9  import {TimelockController} from "@openzeppelin/contracts/governance/TimelockController.sol";
 10  import {IVotes} from "@openzeppelin/contracts/governance/utils/IVotes.sol";
 11  import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
 12  
 13  /// @title EnterpriseDAO
 14  /// @notice Modular Governor with snapshot-safe linear dynamic quorum and TimelockController execution.
 15  /// @dev Voting is block-based because DAOGovernanceToken uses the default ERC-6372 block clock.
 16  ///      The quorum fraction linearly ramps between an immutable minimum and maximum (in basis
 17  ///      points) as the token's historical total supply grows between two immutable supply
 18  ///      thresholds, mirroring the "dynamic quorum" popularised by Nouns DAO style systems:
 19  ///      when supply is small, participation is scarce, so the quorum fraction is lowered;
 20  ///      as supply grows, the required fraction climbs toward its ceiling.
 21  contract EnterpriseDAO is Governor, GovernorSettings, GovernorCountingSimple, GovernorVotes, GovernorTimelockControl {
 22      /// @notice Full construction parameters, packed to keep the constructor stack-safe
 23      ///         without requiring `via_ir` compilation.
 24      /// @custom:member name Governor registry name (e.g. "Enterprise DAO").
 25      /// @custom:member token Governance token implementing IVotes (ERC20Votes).
 26      /// @custom:member timelock TimelockController that executes approved proposals.
 27      /// @custom:member votingDelayBlocks Blocks between proposal creation and vote start.
 28      /// @custom:member votingPeriodBlocks Blocks during which voting is open.
 29      /// @custom:member proposalThreshold Token votes required to create a proposal.
 30      /// @custom:member quorumMinBps Minimum quorum fraction, in basis points of total supply.
 31      /// @custom:member quorumMaxBps Maximum quorum fraction, in basis points of total supply.
 32      /// @custom:member quorumLowSupplyThreshold Supply at or below which the fraction is minimal.
 33      /// @custom:member quorumHighSupplyThreshold Supply at or above which the fraction is maximal.
 34      /// @custom:member minProposalThreshold Governance-adjustable lower threshold bound.
 35      /// @custom:member maxProposalThreshold Governance-adjustable upper threshold bound.
 36      struct GovernorConfig {
 37          string name;
 38          IVotes token;
 39          TimelockController timelock;
 40          uint48 votingDelayBlocks;
 41          uint32 votingPeriodBlocks;
 42          uint256 proposalThreshold;
 43          uint256 quorumMinBps;
 44          uint256 quorumMaxBps;
 45          uint256 quorumLowSupplyThreshold;
 46          uint256 quorumHighSupplyThreshold;
 47          uint256 minProposalThreshold;
 48          uint256 maxProposalThreshold;
 49      }
 50  
 51      /// @notice Basis point denominator shared by all quorum parameters (100% == 10_000).
 52      uint256 public constant QUORUM_DENOMINATOR = 10_000;
 53  
 54      uint256 public immutable dynamicQuorumMinBps;
 55      uint256 public immutable dynamicQuorumMaxBps;
 56      uint256 public immutable quorumLowSupplyThreshold;
 57      uint256 public immutable quorumHighSupplyThreshold;
 58  
 59      uint256 public immutable minimumProposalThreshold;
 60      uint256 public immutable maximumProposalThreshold;
 61  
 62      error InvalidQuorumBounds();
 63      error InvalidProposalThresholdBounds();
 64      error ProposalThresholdOutOfBounds(uint256 requested, uint256 minimum, uint256 maximum);
 65  
 66      constructor(GovernorConfig memory config)
 67          Governor(config.name)
 68          GovernorSettings(config.votingDelayBlocks, config.votingPeriodBlocks, config.proposalThreshold)
 69          GovernorVotes(config.token)
 70          GovernorTimelockControl(config.timelock)
 71      {
 72          if (
 73              config.quorumMinBps > config.quorumMaxBps || config.quorumMaxBps > QUORUM_DENOMINATOR
 74                  || config.quorumLowSupplyThreshold > config.quorumHighSupplyThreshold
 75          ) {
 76              revert InvalidQuorumBounds();
 77          }
 78          if (config.minProposalThreshold > config.maxProposalThreshold) {
 79              revert InvalidProposalThresholdBounds();
 80          }
 81          if (
 82              config.proposalThreshold < config.minProposalThreshold
 83                  || config.proposalThreshold > config.maxProposalThreshold
 84          ) {
 85              revert ProposalThresholdOutOfBounds(
 86                  config.proposalThreshold, config.minProposalThreshold, config.maxProposalThreshold
 87              );
 88          }
 89  
 90          dynamicQuorumMinBps = config.quorumMinBps;
 91          dynamicQuorumMaxBps = config.quorumMaxBps;
 92          quorumLowSupplyThreshold = config.quorumLowSupplyThreshold;
 93          quorumHighSupplyThreshold = config.quorumHighSupplyThreshold;
 94          minimumProposalThreshold = config.minProposalThreshold;
 95          maximumProposalThreshold = config.maxProposalThreshold;
 96      }
 97  
 98      /// @notice Quorum required for a proposal snapshot at `timepoint`, in vote weight.
 99      /// @dev Snapshot-safe: reads historical total supply at `timepoint` (never the current
100      ///      supply), so post-snapshot token movements cannot move the goalposts of a live
101      ///      vote. The fraction itself is interpolated by `quorumFractionAtSupply`.
102      function quorum(uint256 timepoint) public view override returns (uint256) {
103          uint256 snapshotSupply = token().getPastTotalSupply(timepoint);
104          uint256 effectiveBps = quorumFractionAtSupply(snapshotSupply);
105          return Math.mulDiv(snapshotSupply, effectiveBps, QUORUM_DENOMINATOR);
106      }
107  
108      /// @notice Effective quorum fraction (basis points) for a given total supply.
109      /// @dev Linear ramp:
110      ///      - supply <= low threshold  ->  quorumMinBps
111      ///      - supply >= high threshold ->  quorumMaxBps
112      ///      - otherwise                ->  min + (max - min) * (supply - low) / (high - low)
113      ///      When low == high the middle branch is unreachable and the ramp degenerates to a
114      ///      step function, which remains safe.
115      function quorumFractionAtSupply(uint256 totalSupply) public view returns (uint256) {
116          if (totalSupply <= quorumLowSupplyThreshold) {
117              return dynamicQuorumMinBps;
118          }
119          if (totalSupply >= quorumHighSupplyThreshold) {
120              return dynamicQuorumMaxBps;
121          }
122          return dynamicQuorumMinBps
123              + Math.mulDiv(
124              dynamicQuorumMaxBps - dynamicQuorumMinBps,
125              totalSupply - quorumLowSupplyThreshold,
126              quorumHighSupplyThreshold - quorumLowSupplyThreshold
127          );
128      }
129  
130      /// @notice Quorum denominator kept for tooling compatibility (Tally and friends).
131      function quorumDenominator() public view returns (uint256) {
132          return QUORUM_DENOMINATOR;
133      }
134  
135      /// @notice Governance-adjustable proposal threshold, clamped to immutable bounds.
136      /// @dev Re-applies `onlyGovernance` (Solidity overrides do not inherit parent modifiers),
137      ///      but deliberately routes to the internal `_setProposalThreshold` rather than
138      ///      `super.setProposalThreshold`: the parent public function carries its own
139      ///      `onlyGovernance` modifier, and running the whitelist deque check twice drains
140      ///      the deque and reverts during legitimate proposal execution.
141      function setProposalThreshold(uint256 newProposalThreshold) public override(GovernorSettings) onlyGovernance {
142          if (newProposalThreshold < minimumProposalThreshold || newProposalThreshold > maximumProposalThreshold) {
143              revert ProposalThresholdOutOfBounds(
144                  newProposalThreshold, minimumProposalThreshold, maximumProposalThreshold
145              );
146          }
147          _setProposalThreshold(newProposalThreshold);
148      }
149  
150      // ------------------------------------------------------------------
151      // Linearisation glue: required explicit overrides.
152      // ------------------------------------------------------------------
153  
154      function votingDelay() public view override(Governor, GovernorSettings) returns (uint256) {
155          return super.votingDelay();
156      }
157  
158      function votingPeriod() public view override(Governor, GovernorSettings) returns (uint256) {
159          return super.votingPeriod();
160      }
161  
162      function proposalThreshold() public view override(Governor, GovernorSettings) returns (uint256) {
163          return super.proposalThreshold();
164      }
165  
166      function clock() public view override(Governor, GovernorVotes) returns (uint48) {
167          return super.clock();
168      }
169  
170      // solhint-disable-next-line func-name-mixedcase
171      function CLOCK_MODE() public view override(Governor, GovernorVotes) returns (string memory) {
172          return super.CLOCK_MODE();
173      }
174  
175      function _getVotes(address account, uint256 timepoint, bytes memory params)
176          internal
177          view
178          override(Governor, GovernorVotes)
179          returns (uint256)
180      {
181          return super._getVotes(account, timepoint, params);
182      }
183  
184      function proposalNeedsQueuing(uint256 proposalId)
185          public
186          view
187          override(Governor, GovernorTimelockControl)
188          returns (bool)
189      {
190          return super.proposalNeedsQueuing(proposalId);
191      }
192  
193      function state(uint256 proposalId) public view override(Governor, GovernorTimelockControl) returns (ProposalState) {
194          return super.state(proposalId);
195      }
196  
197      function _queueOperations(
198          uint256 proposalId,
199          address[] memory targets,
200          uint256[] memory values,
201          bytes[] memory calldatas,
202          bytes32 descriptionHash
203      ) internal override(Governor, GovernorTimelockControl) returns (uint48) {
204          return super._queueOperations(proposalId, targets, values, calldatas, descriptionHash);
205      }
206  
207      function _executeOperations(
208          uint256 proposalId,
209          address[] memory targets,
210          uint256[] memory values,
211          bytes[] memory calldatas,
212          bytes32 descriptionHash
213      ) internal override(Governor, GovernorTimelockControl) {
214          super._executeOperations(proposalId, targets, values, calldatas, descriptionHash);
215      }
216  
217      function _cancel(
218          address[] memory targets,
219          uint256[] memory values,
220          bytes[] memory calldatas,
221          bytes32 descriptionHash
222      ) internal override(Governor, GovernorTimelockControl) returns (uint256) {
223          return super._cancel(targets, values, calldatas, descriptionHash);
224      }
225  
226      function _executor() internal view override(Governor, GovernorTimelockControl) returns (address) {
227          return super._executor();
228      }
229  
230      function supportsInterface(bytes4 interfaceId) public view override(Governor) returns (bool) {
231          return super.supportsInterface(interfaceId);
232      }
233  }
