17  /// @dev Handler-based invariant actor: every action available on the treasury,
18  ///      driven by fuzzed selectors. Ghost state tracks approved packages.
19  contract TreasuryHandler is Test {
20      DAOTreasuryExecutionEngine public immutable treasury;
21      InvariantTarget public immutable target;
22  
23      address public immutable governance;
24      address public immutable guardian;
25  
26      // Ghost bookkeeping for invariants.
27      mapping(bytes32 => bool) public approved;
28      bytes32[] public approvedList;
29  
30      constructor(DAOTreasuryExecutionEngine t, InvariantTarget tgt, address gov, address grd) {
31          treasury = t;
32          target = tgt;
33          governance = gov;
34          guardian = grd;
35      }
36  
37      function approve(uint256 valueSeed, uint8 tier) external {
38          tier = uint8(uint256(bound(tier, 0, 3)));
39          (, uint256 cap,) = treasury.tierConfig(tier);
40          uint256 value = uint256(bound(valueSeed, 0, cap));
41          vm.prank(governance);
42          bytes32 id = treasury.approvePackage(address(target), value, "", tier, 0, bytes32(0));
43          approved[id] = true;
44          approvedList.push(id);
45      }
46  
47      function execute(uint256 index) external {
48          uint256 len = approvedList.length;
49          if (len == 0) return;
50          bytes32 id = approvedList[uint256(bound(index, 0, len - 1))];
51          DAOTreasuryExecutionEngine.Package memory pkg = treasury.getPackage(id);
52          if (pkg.executed || pkg.cancelled) return;
53          if (block.timestamp < pkg.executeAfter) vm.warp(uint256(pkg.executeAfter) + 1);
54  
55          try treasury.executePackage(id) {
56          // success: package now executed
57          }
58              catch {}
59      }
60  
61      function approvedListLength() external view returns (uint256) {
62          return approvedList.length;
63      }
64  
65      function guardianCancel(uint256 index) external {
66          uint256 len = approvedList.length;
67          if (len == 0) return;
68          bytes32 id = approvedList[uint256(bound(index, 0, len - 1))];
69  
70          try treasury.getPackage(id) returns (DAOTreasuryExecutionEngine.Package memory pkg) {
71              if (pkg.executed || pkg.cancelled) return;
72              if (block.timestamp >= pkg.executeAfter) vm.warp(block.timestamp - 1); // squeeze inside window
73              vm.prank(guardian);
74              try treasury.cancelPackage(id) {} catch {}
75          } catch {}
76      }
77  
78      function warpTime(uint256 jump) external {
79          vm.warp(block.timestamp + bound(jump, 0, 400 days));
80      }

