10  /// @title DAOGovernanceToken
11  /// @notice Fixed-supply ERC20 governance token with EIP-2612 permits and historical vote
12  ///         checkpoints. Supply is minted exactly once, in the constructor, to a bootstrap
13  ///         recipient; there is no owner, no mint function and no snapshot function by design.
14  /// @dev ERC20Votes records checkpoints on delegation/transfers/mints/burns, so the Governor
15  ///      reads historical voting power at proposal snapshot timepoints; current balances are
16  ///      never consulted for an active vote. Permits and vote-checkpointing share the same
17  ///      nonce namespace through the `nonces` override below (per EIP-2612 + ERC-6372).
18  contract DAOGovernanceToken is ERC20, ERC20Permit, ERC20Votes, ERC20Burnable {
19      error InvalidInitialRecipient();
20  
21      constructor(string memory name_, string memory symbol_, address initialRecipient, uint256 initialSupply)
22          ERC20(name_, symbol_)
23          ERC20Permit(name_)
24      {
25          if (initialRecipient == address(0)) revert InvalidInitialRecipient();
26          _mint(initialRecipient, initialSupply);
27      }
28  
29      /// @dev Resolve the ERC20/ERC20Votes state-update collision (checkpoint on every move).
30      function _update(address from, address to, uint256 value) internal override(ERC20, ERC20Votes) {
31          super._update(from, to, value);
32      }
33  
34      /// @dev Resolve the ERC20Permit/Nonces nonce collision so permits and delegations
35      ///      consume the same counter without clobbering each other.
36      function nonces(address owner) public view override(ERC20Permit, Nonces) returns (uint256) {
37          return super.nonces(owner);
38      }
39  }
