 14  /// @title DAOTreasuryExecutionEngine
 15  /// @notice Multi-asset treasury with governance-approved, delayed execution packages.
 16  /// @dev The TimelockController should hold governance authority over this contract.
 17  ///      Every package binds target/value/calldata/tier/nonce into an immutable package id.
 18  ///      Execution is permissionless after the package's tier delay, improving liveness.
 19  ///
 20  ///      Guardian power is deliberately time-bound: a guardian may cancel a package only
 21  ///      while it is still in quarantine (before its `executeAfter` timepoint). Once the
 22  ///      quarantine window has elapsed, cancellation is a governance-only decision, so a
 23  ///      compromised guardian cannot permanently suppress execution of approved packages.
 24  contract DAOTreasuryExecutionEngine is AccessControl, Pausable, ReentrancyGuard, ERC721Holder, ERC1155Holder {
 25      using SafeERC20 for IERC20;
 26  
 27      bytes32 public constant GOVERNANCE_ROLE = keccak256("GOVERNANCE_ROLE");
 28      bytes32 public constant GUARDIAN_ROLE = keccak256("GUARDIAN_ROLE");
 29  
 30      uint8 public constant TIER_LOW = 0;
 31      uint8 public constant TIER_MEDIUM = 1;
 32      uint8 public constant TIER_HIGH = 2;
 33      uint8 public constant TIER_CRITICAL = 3;
 34      uint8 public constant MAX_TIER = TIER_CRITICAL;
 35  
 36      /// @notice Upper bound for any tier delay. A quarantine longer than a year is
 37      ///         nonsensical for this system and would risk `uint48` truncation abuse.
 38      uint48 public constant MAX_TIER_DELAY = 365 days;
 39  
 40      /// @notice Maximum scheduling horizon: a package must be executable (executeAfter
 41      ///         must be within this window after approval) so governance cannot park a
 42      ///         package for a decade ahead.
 43      uint48 public constant MAX_PACKAGE_EXPIRY = 365 days;
 44  
 45      struct TierConfig {
 46          uint48 delay;
 47          uint256 maxNativeValue;
 48          bool enabled;
 49      }
 50  
 51      /// @dev Field order packs `executeAfter`, `tier`, `executed` and `cancelled` into one
 52      ///      storage slot. `data` is wiped after execution to refund gas and keep state lean.
 53      ///      `expiresAt` bounds the execution window: expired packages can never execute.
 54      ///      `predecessor` enforces ordering: a package can only execute once its
 55      ///      predecessor has executed.
 56      struct Package {
 57          address target;
 58          uint256 value;
 59          bytes data;
 60          uint48 executeAfter;
 61          uint8 tier;
 62          bool executed;
 63          bool cancelled;
 64          uint256 nonce;
 65          uint48 expiresAt;
 66          bytes32 predecessor;
 67      }
 68  
 69      mapping(uint8 tier => TierConfig config) public tierConfig;
 70      mapping(bytes32 packageId => Package package_) private _packages;
 71      uint256 public nextPackageNonce = 1;
 72  
 73      /// @notice Optional destination allowlist. When enabled, packages may only target
 74      ///         allowlisted addresses. Toggle and list are governance-controlled.
 75      bool public targetAllowlistEnabled;
 76      mapping(address allowed => bool isAllowed) public targetAllowlist;
 77  
 78      /// @notice Optional per-asset reserve floors: the treasury refuses to execute a
 79      ///         package that would push its native or ERC20 balance below the floor.
 80      ///         ERC20 floors of 0 disable the check for that token.
 81      uint256 public nativeReserveFloor;
 82      mapping(IERC20 token => uint256 floor) public erc20ReserveFloors;
 83  
 84      event PackageApproved(
 85          bytes32 indexed packageId,
 86          address indexed target,
 87          uint256 value,
 88          uint8 indexed tier,
 89          uint256 nonce,
 90          uint48 executeAfter,
 91          bytes32 dataHash
 92      );
 93      event PackageApprovedV2(
 94          bytes32 indexed packageId,
 95          address indexed target,
 96          uint256 value,
 97          uint8 indexed tier,
 98          uint256 nonce,
 99          uint48 executeAfter,
100          uint48 expiresAt,
101          bytes32 predecessor,
102          bytes32 dataHash
103      );
104      event PackageExecuted(bytes32 indexed packageId, address indexed target, uint256 value, bytes returnData);
105      event PackagesBatchExecuted(uint256 count);
106      event PackageCancelled(bytes32 indexed packageId, address indexed caller);
107      event PackageExpired(bytes32 indexed packageId);
108      event TierConfigured(uint8 indexed tier, uint48 delay, uint256 maxNativeValue, bool enabled);
109      event TreasuryPaused(address indexed guardian);
110      event TreasuryUnpaused(address indexed governance);
111      event NativeDeposited(address indexed sender, uint256 value);
112      event ERC20Deposited(address indexed sender, address token, uint256 amount);
113      event ERC721Deposited(address indexed sender, address token, uint256 tokenId);
114      event ERC1155Deposited(address indexed sender, address token, uint256 indexed tokenId, uint256 amount);
115      event TargetAllowlistToggled(bool enabled);
116      event TargetAllowlistUpdated(address indexed target, bool allowed);
117      event ReserveFloorsConfigured(uint256 nativeFloor);
118      event ERC20ReserveFloorConfigured(address indexed token, uint256 floor);
