148          _setRoleAdmin(GOVERNANCE_ROLE, GOVERNANCE_ROLE);
149          _setRoleAdmin(GUARDIAN_ROLE, GOVERNANCE_ROLE);
150          _grantRole(GOVERNANCE_ROLE, timelockExecutor);
151          _grantRole(GUARDIAN_ROLE, guardian);
152  
153          _configureTier(TIER_LOW, 1 days, 250 ether, true);
154          _configureTier(TIER_MEDIUM, 3 days, 100 ether, true);
155          _configureTier(TIER_HIGH, 7 days, 25 ether, true);
156          _configureTier(TIER_CRITICAL, 14 days, 5 ether, true);
157      }
