248      /// @notice Cancel a package that has expired: anyone can call, keeps state clean.
249      function closeExpiredPackage(bytes32 packageId) external {
250          Package storage package_ = _packages[packageId];
251          if (package_.target == address(0)) revert PackageNotFound(packageId);
252          if (package_.executed || package_.cancelled) revert PackageAlreadyFinalized(packageId);
253          if (package_.expiresAt == 0 || block.timestamp < package_.expiresAt) {
254              revert PackageNotReady(packageId, package_.expiresAt);
255          }
256  
257          package_.cancelled = true; // finalized as cancelled; never executable
258          emit PackageExpired(packageId);
259      }
