296      /// @dev Shared engine for single and batch execution.
297      function _executePackage(bytes32 packageId) private returns (bytes memory returnData) {
298          Package storage package_ = _packages[packageId];
299          if (package_.target == address(0)) revert PackageNotFound(packageId);
300          if (package_.executed || package_.cancelled) revert PackageAlreadyFinalized(packageId);
301          if (block.timestamp < package_.executeAfter) {
302              revert PackageNotReady(packageId, package_.executeAfter);
303          }
304          if (package_.expiresAt != 0 && block.timestamp >= package_.expiresAt) {
305              revert PackageExpiredError(packageId, package_.expiresAt);
306          }
307          if (package_.predecessor != bytes32(0)) {
308              Package storage pred = _packages[package_.predecessor];
309              if (!pred.executed) revert PredecessorNotExecuted(packageId, package_.predecessor);
310          }
311          if (package_.value > 0) {
312              uint256 balance = address(this).balance;
313              if (balance < package_.value || balance - package_.value < nativeReserveFloor) {
314                  revert ReserveFloorBreached(balance, nativeReserveFloor);
315              }
316          }
317  
318          // Checks-effects-interactions. A revert from the external call rolls the status
319          // change back; the treasury itself always supplies the native value.
320          package_.executed = true;
321  
322          (bool success, bytes memory data_) = package_.target.call{value: package_.value}(package_.data);
323          if (!success) revert ExecutionFailed(packageId, data_);
324  
325          // Wipe the calldata payload after success: refunds gas, keeps long-term state lean.
326          // Metadata (target, value, tier, nonce, executeAfter, flags) is retained.
327          delete package_.data;
328  
329          emit PackageExecuted(packageId, package_.target, package_.value, data_);
330          return data_;
331      }
332  
333      /// @notice Cancel a package: guardians only during quarantine, governance at any time.
334      /// @dev Guardian cancellation is restricted to the window before `executeAfter`, so a
335      ///      compromised guardian cannot suppress approved packages indefinitely. Governance
336      ///      (the timelock path, typically a multi-day process) retains unlimited cancellation.
337      function cancelPackage(bytes32 packageId) external {
338          Package storage package_ = _packages[packageId];
339          if (package_.target == address(0)) revert PackageNotFound(packageId);
340          if (package_.executed || package_.cancelled) revert PackageAlreadyFinalized(packageId);
341  
342          bool isGovernance = hasRole(GOVERNANCE_ROLE, msg.sender);
343          bool isGuardian = hasRole(GUARDIAN_ROLE, msg.sender);
344  
345          if (!isGovernance && !isGuardian) {
346              revert CallerNotGovernanceOrGuardian(msg.sender);
347          }
348          if (!isGovernance && block.timestamp >= package_.executeAfter) {
349              revert GuardianCancelWindowClosed(packageId, package_.executeAfter);
350          }
351  
352          package_.cancelled = true;
353          emit PackageCancelled(packageId, msg.sender);
354      }
